/**
 * Small dependency-free helpers shared by the dsh-vigil Host plugin.
 *
 * The plugin deliberately ships with zero npm dependencies: it is installed from
 * a local directory into a Harness profile, so every import must resolve from
 * Node builtins or from files inside this package. Keeping the helpers here (and
 * the code plain ES modules) also means the shipped files are the audited files
 * — nothing is generated by a build step.
 *
 * @module dsh-vigil/util
 */

import { createHash, randomBytes } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, renameSync, statSync, unlinkSync, writeFileSync } from 'node:fs'
import { homedir } from 'node:os'
import { isAbsolute, join, normalize, relative, resolve, sep } from 'node:path'

/** @returns {string} the OS user's home directory. */
export function getHomeDir() {
  return process.env.HOME || process.env.USERPROFILE || homedir()
}

/**
 * The Harness home directory. `DSH_HOME` is set for profile-launched Harnesses;
 * `~/.dsh` is the documented fallback.
 * @returns {string}
 */
export function getDshHome() {
  const fromEnv = process.env.DSH_HOME
  if (typeof fromEnv === 'string' && fromEnv.trim() !== '') return resolve(fromEnv)
  return join(getHomeDir(), '.dsh')
}

/**
 * Expand a leading `~` and process environment references in a configured path.
 * @param {string} value
 * @returns {string}
 */
export function expandPath(value) {
  if (typeof value !== 'string') return ''
  let out = value.trim()
  if (out === '') return ''
  if (out === '~') return getHomeDir()
  if (out.startsWith('~/') || out.startsWith('~\\')) out = join(getHomeDir(), out.slice(2))
  out = out.replace(/%([A-Za-z_][A-Za-z0-9_]*)%/g, (match, name) => process.env[name] ?? match)
  out = out.replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)\}/g, (match, name) => process.env[name] ?? match)
  const home = getHomeDir()
  out = out.replace(/^\$HOME(?=$|[\\/])/, home)
  return out
}

/**
 * Resolve a user/config supplied path to an absolute path.
 * @param {string} value
 * @param {string} [base] base directory for relative paths; defaults to process.cwd()
 * @returns {string}
 */
export function resolvePath(value, base) {
  const expanded = expandPath(value)
  if (expanded === '') return ''
  return resolve(isAbsolute(expanded) ? expanded : join(base || process.cwd(), expanded))
}

/**
 * Case-normalized key for path comparison. Windows paths compare
 * case-insensitively; other platforms compare exactly.
 * @param {string} value
 * @returns {string}
 */
export function pathKey(value) {
  const normalized = normalize(value)
  return process.platform === 'win32' ? normalized.toLowerCase() : normalized
}

/**
 * Whether `child` is `parent` itself or a descendant of it.
 * @param {string} parent
 * @param {string} child
 * @returns {boolean}
 */
export function isWithin(parent, child) {
  if (!parent || !child) return false
  const rel = relative(normalize(parent), normalize(child))
  if (rel === '') return true
  if (isAbsolute(rel)) return false
  return !rel.startsWith(`..${sep}`) && rel !== '..'
}

/**
 * Relative path from `base` with POSIX separators (stable in reports).
 * @param {string} base
 * @param {string} target
 * @returns {string}
 */
export function toPosixRelative(base, target) {
  return relative(base, target).split(sep).join('/')
}

/**
 * SHA-256 hex digest of a string or buffer.
 * @param {string|Uint8Array} input
 * @returns {string}
 */
export function sha256(input) {
  return createHash('sha256').update(input).digest('hex')
}

/**
 * Deterministic JSON for hashing records whose key order must not matter.
 * Only plain objects/arrays/primitives are expected here.
 * @param {unknown} value
 * @returns {string}
 */
export function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value)
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`
  const entries = Object.keys(/** @type {Record<string, unknown>} */ (value)).sort()
  return `{${entries.map(key => `${JSON.stringify(key)}:${stableStringify(/** @type {Record<string, unknown>} */ (value)[key])}`).join(',')}}`
}

/**
 * Create a directory tree, ignoring races where another writer won.
 * @param {string} dir
 * @returns {boolean} whether the directory exists afterwards
 */
export function ensureDir(dir) {
  try {
    mkdirSync(dir, { recursive: true })
    return true
  } catch {
    return existsSync(dir)
  }
}

/**
 * Write a file through a sibling temporary file so a crash cannot truncate the
 * previous content.
 * @param {string} file
 * @param {string|Uint8Array} content
 * @returns {boolean} whether the write succeeded
 */
export function atomicWriteFile(file, content) {
  const tmp = `${file}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`
  try {
    ensureDir(join(file, '..'))
    writeFileSync(tmp, content)
    renameSync(tmp, file)
    return true
  } catch {
    try {
      unlinkSync(tmp)
    } catch {
      // best effort
    }
    return false
  }
}

/**
 * Atomically persist a JSON document.
 * @param {string} file
 * @param {unknown} value
 * @returns {boolean}
 */
export function atomicWriteJson(file, value) {
  return atomicWriteFile(file, `${JSON.stringify(value, null, 2)}\n`)
}

/**
 * Read and parse JSON; returns `undefined` for absent or malformed files.
 * @param {string} file
 * @returns {any}
 */
export function readJson(file) {
  try {
    return JSON.parse(readFileSync(file, 'utf8'))
  } catch {
    return undefined
  }
}

/**
 * File size in bytes, or `undefined` when the path is not a regular file.
 * @param {string} file
 * @returns {number|undefined}
 */
export function fileSize(file) {
  try {
    const stat = statSync(file)
    return stat.isFile() ? stat.size : undefined
  } catch {
    return undefined
  }
}

/**
 * Human readable byte size. Uses binary units (KiB/MiB/GiB), matching how
 * deletion thresholds are configured.
 * @param {number} bytes
 * @returns {string}
 */
export function formatBytes(bytes) {
  if (!Number.isFinite(bytes) || bytes < 0) return '?'
  if (bytes < 1024) return `${bytes} B`
  const units = ['KiB', 'MiB', 'GiB', 'TiB']
  let value = bytes / 1024
  let index = 0
  while (value >= 1024 && index < units.length - 1) {
    value /= 1024
    index += 1
  }
  return `${value >= 100 ? Math.round(value) : value.toFixed(1)} ${units[index]}`
}

/** @returns {string} ISO timestamp of the current instant. */
export function nowIso() {
  return new Date().toISOString()
}

/**
 * Clamp a string to a maximum length, marking truncation explicitly so a
 * truncated audit record is never mistaken for the full value.
 * @param {unknown} value
 * @param {number} max
 * @returns {string}
 */
export function truncate(value, max) {
  const text = typeof value === 'string' ? value : value === undefined || value === null ? '' : String(value)
  if (text.length <= max) return text
  return `${text.slice(0, Math.max(0, max - 1))}…`
}

/**
 * Remove the current user's home directory (and the Harness home) from a string
 * so paths in logs and reports do not leak the account name.
 * @param {string} text
 * @returns {string}
 */
export function scrubHome(text) {
  if (typeof text !== 'string' || text === '') return ''
  const home = getHomeDir()
  if (!home) return text
  const variants = [home, home.replace(/\\/g, '\\\\')]
  let out = text
  for (const variant of variants) {
    if (variant.length > 2) out = out.split(variant).join('~')
  }
  const dshHome = process.env.DSH_HOME
  if (typeof dshHome === 'string' && dshHome.length > 2) {
    out = out.split(dshHome).join('<DSH_HOME>').split(dshHome.replace(/\\/g, '\\\\')).join('<DSH_HOME>')
  }
  return out
}

/**
 * @param {string} [prefix]
 * @returns {string} a short random id safe for file names
 */
export function randomId(prefix = '') {
  return `${prefix}${Date.now().toString(36)}-${randomBytes(4).toString('hex')}`
}

/**
 * @param {unknown} value
 * @returns {value is Record<string, unknown>}
 */
export function isPlainObject(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/**
 * Recursively merge `overrides` into `base` without mutating either. Arrays are
 * replaced, not concatenated: a preset's protected-root list is a complete
 * statement of intent.
 * @param {Record<string, unknown>} base
 * @param {Record<string, unknown>} overrides
 * @returns {Record<string, unknown>}
 */
export function deepMerge(base, overrides) {
  const result = { ...base }
  for (const [key, value] of Object.entries(overrides || {})) {
    if (value === undefined) continue
    const previous = result[key]
    if (isPlainObject(previous) && isPlainObject(value)) {
      result[key] = deepMerge(previous, value)
    } else {
      result[key] = value
    }
  }
  return result
}

/**
 * Run `fn` and capture a thrown error as a value.
 * @template T
 * @param {() => T} fn
 * @returns {{ ok: true, value: T } | { ok: false, error: Error }}
 */
export function attempt(fn) {
  try {
    return { ok: true, value: fn() }
  } catch (error) {
    return { ok: false, error: error instanceof Error ? error : new Error(String(error)) }
  }
}
